{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Backwash\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Reverse reverb and creative effects for REAPER: capture audio, render a reversed reverb tail and shape it with risers, saturation, sweeps, modulation, tremolo, auto-pan and bitcrusher.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
